#include <stdio.h>

int main(void) {
    int n = 8;
    long del_total = 0;
    for (int p = 0; p < n; p++) {
        int shifts = n - 1 - p;          /* 删除下标 p，其后元素整体前移 */
        del_total += shifts;
        printf("删除下标 %d：搬移 %d 个元素\n", p, shifts);
    }
    printf("删除合计搬移 = %ld 次\n", del_total);

    /* 头插 N 次的累计搬移：第 k 次头插要搬移已有的 k 个元素 */
    long head_insert_total = 0;
    for (int k = 0; k < n; k++) head_insert_total += k;
    printf("连续头插 %d 次的累计搬移 = %ld 次（≈ n^2/2，即 O(n^2)）\n",
           n, head_insert_total);
    printf("结论：循环中头插会把线性算法退化成平方级\n");
    return 0;
}
